// client/src/app/services/orders.service.ts
import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

// Order input for creating a new order
export interface OrderItemIn { product_id: number; quantity: number; }
export interface OrderCreate {
  items: OrderItemIn[];
  payment_method: string;
  shipping_address: string;
  contact_name: string;
  contact_email: string;
  contact_phone: string;
}

// Order output from backend
export interface OrderItemOut {
  product_id: number;
  quantity: number;
  unit_price_cents: number;
}

export interface OrderOut {
  id: number;
  status: 'PENDING_PAYMENT' | 'PAID' | 'CANCELLED';
  total_amount_cents: number;
  payment_method?: string;
  shipping_address?: string;
  contact_name?: string;
  contact_email?: string;
  contact_phone?: string;
  items: OrderItemOut[];
}

@Injectable({ providedIn: 'root' })
export class OrdersService {

  private apiBase = 'http://127.0.0.1:8000'; // Your backend URL

  constructor(private http: HttpClient) {}

  // List all orders for current user
  list(): Observable<OrderOut[]> {
    return this.http.get<OrderOut[]>(`${this.apiBase}/orders`);
  }

  // Get a single order by ID
  get(id: number): Observable<OrderOut> {
    return this.http.get<OrderOut>(`${this.apiBase}/orders/${id}`);
  }

  // Create a new order
  create(payload: OrderCreate): Observable<OrderOut> {
    return this.http.post<OrderOut>(`${this.apiBase}/orders`, payload);
  }

  // Initiate Stripe payment for an order
  createStripeSession(orderId: number): Observable<{ checkout_url: string }> {
    return this.http.post<{ checkout_url: string }>(`${this.apiBase}/payments/stripe-session/${orderId}`, {});
  }

  // Cancel an order
  cancel(orderId: number): Observable<OrderOut> {
    return this.http.post<OrderOut>(`${this.apiBase}/orders/${orderId}/cancel`, {});
  }
}
